proc sql;
	create table funda5 as select 
	distinct a.*, b.infocode 
	from funda4 as a left join link.Ds2ws_linktable as b 
on a.code=b.code 
group by a.ws_id, a.fyear;

data dsf;
set ds.wrds_ds2dsf;
where ret is not missing and infocode is not missing;
keep infocode ret marketdate;
run;

data dsf1;
set dsf;
lnret=log(1+ret);
run;

proc sql;
	create table funda6 as select 
	distinct a.*, exp(sum(b.lnret))-1 as yr_ret, std(ret) as ret_vol 
	from funda5 as a left join dsf1 as b 
on a.infocode=b.infocode and a.datadate>=b.marketdate>l1datadate 
group by a.ws_id, a.fyear;

